import json,os,re
data=json.load(open('deliverable/citations.json'))
idx=open('library/INDEX.md').read()
allowed={"in force","superseded","vacated"}
probs=[]
for i,d in enumerate(data):
    for k in ("cite","library_file","proposition","status_checked"):
        if k not in d or not str(d[k]).strip(): probs.append(f"entry {i} missing {k}")
    if d.get("status_checked") not in allowed: probs.append(f"entry {i} bad status")
    f=d.get("library_file","")
    if not os.path.exists(f): probs.append(f"entry {i} file missing")
    if f and f not in idx: probs.append(f"entry {i} not in INDEX")
    if "memo_bank" in f: probs.append(f"entry {i} cites memo bank")
print("entries:",len(data),"problems:",probs or "NONE")
# stale numbers sweep
memo=open('deliverable/memo.md').read()
for s in ["603.6","1.0%–9.0%","0.1%–3.0%","§1660.5","−603k","549.6","670k","15%–40%"]:
    if s in memo: print("STALE:",s)
print("stale sweep done")
# every library file path mentioned in memo exists
for m in set(re.findall(r'library/[a-z0-9_.]+\.md', memo)):
    if not os.path.exists(m): print("BAD PATH in memo:", m)
print("path sweep done")
EOF

